#include <iomanip>
#include <iostream>
#include <limits>
#include <optional>

std::optional<double> safeRatio(double a, double b) {
    if (b == 0) {
        if (a == 0) {
            return std::nullopt;
        }
        const double inf = std::numeric_limits<double>::infinity();
        return a > 0 ? inf : -inf;
    }
    return a / b;
}

int main() {
    double a, b;
    std::cin >> a >> b;
    const double inf = std::numeric_limits<double>::infinity();
    std::optional<double> result = safeRatio(a, b);
    if (!result) {
        std::cout << "undefined\n";
    } else if (*result == inf) {
        std::cout << "infinity\n";
    } else if (*result == -inf) {
        std::cout << "-infinity\n";
    } else {
        std::cout << std::fixed << std::setprecision(2) << *result << "\n";
    }
    return 0;
}

