package main

import (
	"fmt"
	"math"
)

func safeRatio(a, b float64) *float64 {
	if b == 0 {
		if a == 0 {
			return nil
		}
		inf := math.Inf(1)
		if a < 0 {
			inf = math.Inf(-1)
		}
		return &inf
	}
	result := a / b
	return &result
}

func main() {
	var a, b float64
	fmt.Scan(&a, &b)
	result := safeRatio(a, b)
	if result == nil {
		fmt.Println("undefined")
	} else if math.IsInf(*result, 1) {
		fmt.Println("infinity")
	} else if math.IsInf(*result, -1) {
		fmt.Println("-infinity")
	} else {
		fmt.Printf("%.2f\n", *result)
	}
}
